insert into kafaa_pathways (id, skill_id, level, title_en, title_ar, summary_en, summary_ar, outcome_en, outcome_ar, envelope_months, weekly_hours, status, listed, version, benchmark_ids, sources, updated_by, updated_at, sort) values
('pw-et-system-integration', 'sk-fs-gr-h2heat', 2, 'Energy-system integration: from awareness to practitioner', 'تكامل منظومة الطاقة: من الوعي إلى الممارسة', 'Hydrogen, process heat and the grid in one route: three value chains, the interfaces with a nuclear plant and the skills they need. Concept learning; no deployment decision implied.', 'الهيدروجين والحرارة الصناعية والشبكة في مسار واحد: ثلاث سلاسل قيمة، والواجهات مع المحطة النووية، والمهارات التي تحتاجها. تعلّم مفاهيمي، ولا يُفهم منه أي قرار بالنشر.', 'You can explain how nuclear heat and electricity could serve hydrogen, industry and the grid, and where the safety boundary sits.', 'تستطيع شرح كيف يمكن للحرارة والكهرباء النوويتين خدمة الهيدروجين والصناعة والشبكة، وأين تقع حدود السلامة.', 6, 2, 'published', true, 1, array['ENERGY-JOBS','NEA']::text[], '[{"id":"fs42-nea-plan2035","label":"OECD-NEA · Plan 2035 vision paper: Scaling Technology, Growing Careers, Securing the Future (Oct 2025)","url":"https://www.oecd-nea.org/upload/docs/application/pdf/2025-10/plan_2035_-_vision_paper_-_final_version.pdf","accessed":"2026-10-10"},{"id":"fs42-iea-wee","label":"NucNet · IEA World Energy Employment 2025: jobs growth in nuclear (Dec 2025)","url":"https://smr.nucnet.org/news/jobs-growth-in-nuclear-surged-in-2024-and-will-continue-to-expand-despite-headwinds-iea-report-12-5-2025","accessed":"2026-10-10"},{"id":"fs42-irena-jobs","label":"EU BUILD UP · IRENA and ILO, Renewable Energy and Jobs: Annual Review 2025","url":"https://build-up.ec.europa.eu/en/resources-and-tools/publications/annual-review-2025-renewable-energy-and-jobs","accessed":"2026-10-10"}]'::jsonb, 'p-training-mgr', '2026-10-11T08:00:00Z', 96),
('pw-et-esg-managers', 'sk-fs-gr-esg', 1, 'ESG and GHG literacy for managers', 'الإلمام بالحوكمة البيئية والاجتماعية وغازات الدفيئة للمديرين', 'A short route for managers and reporting staff: greenhouse-gas accounting basics, sustainability and human capital reporting concepts, and a check that counts toward MC-CLEAN-ENERGY.', 'مسار قصير للمديرين وموظفي إعداد التقارير: أساسيات محاسبة غازات الدفيئة، ومفاهيم تقارير الاستدامة ورأس المال البشري، وفحص يُحتسب ضمن الاعتماد المصغّر MC-CLEAN-ENERGY.', 'You can read a sustainability or human capital disclosure, explain its main metrics and question a figure before you repeat it.', 'تستطيع قراءة إفصاح عن الاستدامة أو رأس المال البشري، وشرح مقاييسه الرئيسية، ومساءلة الرقم قبل تكراره.', 3, 1, 'published', true, 1, array['GREENCOMP','ISO30414','ENERGY-JOBS']::text[], '[{"id":"fs43-iso30414","label":"ISO TC 260 · ISO 30414:2025, strengthening human capital reporting (24 Aug 2025)","url":"https://committee.iso.org/sites/tc260/home/news/content-left-area/news-and-updates/iso-30414-2025-strengthening-hum.html","accessed":"2026-10-10"},{"id":"fs41-greencomp","label":"European Commission JRC · GreenComp, the European sustainability competence framework (2022)","url":"https://joint-research-centre.ec.europa.eu/greencomp","accessed":"2026-10-10"}]'::jsonb, 'p-training-mgr', '2026-10-11T08:00:00Z', 97)
