('pw-et-system-integration:v1:s2', 'pw-et-system-integration', 2, 'learn', 'Practitioner: hydrogen and process-heat interfaces', 'الممارسة: واجهات الهيدروجين والحرارة الصناعية', 16, array['course:c-fs-h2heat','course:c-adv-intro']::text[], true, 1),
